mapper.select:
SELECT id, user_id as userId, CASE WHEN image LIKE 'http%' THEN image ELSE CONCAT('https://java-web-ai388.oss-cn-beijing.aliyuncs.com/', image) END AS imagePath, test_time as testTime, is_gland_face as isGlandFace, CASE WHEN level LIKE '%轻%' OR level LIKE '%微%' THEN '轻度' WHEN level LIKE '%中%' OR level LIKE '%等%' THEN '中期' WHEN level LIKE '%重%' THEN '重度' ELSE level END as level, probability as confidence, visualization_description as visualizationDescription FROM test_result WHERE user_id = #{userId}
AND test_time >= #{startDate}
AND test_time <= #{endDate}
AND is_gland_face = #{isGlandFace}
AND (level LIKE "%轻%" OR level LIKE "%微%")
AND (level LIKE "%中%" OR level LIKE "%等%")
AND level LIKE "%重%"
AND level = #{level}
ORDER BY test_time DESC

